import { useEffect, useState } from "react";
import { io } from "socket.io-client";

const socket = io("http://localhost:5000");

function PatientDashboard() {

  const [queues, setQueues] = useState([]);
  const [joined, setJoined] = useState(false);

  const [form, setForm] = useState({
    patientName: "",
    doctor: "",
    department: "",
    date: ""
  });

  // GET QUEUE
  const fetchQueues = async () => {
    const res = await fetch("http://localhost:5000/api/queue/all");
    const data = await res.json();
    setQueues(data);
  };

  // SOCKET
  useEffect(() => {
    fetchQueues();

    socket.on("queueUpdated", () => {
      fetchQueues();
    });

    socket.on("notification", (msg) => {
      const div = document.createElement("div");
      div.innerText = msg;
      div.style.position = "fixed";
      div.style.top = "20px";
      div.style.right = "20px";
      div.style.background = "#16a34a";
      div.style.color = "white";
      div.style.padding = "10px";
      div.style.borderRadius = "8px";

      document.body.appendChild(div);
      setTimeout(() => div.remove(), 4000);
    });

    return () => socket.off();
  }, []);

  // BOOK OP
  const bookOP = async () => {
    await fetch("http://localhost:5000/api/queue/add", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(form)
    });

    setForm({
      patientName: "",
      doctor: "",
      department: "",
      date: ""
    });
  };

  // JOIN QUEUE
  const joinQueue = async (id) => {
    await fetch(`http://localhost:5000/api/queue/join/${id}`, {
      method: "PUT"
    });

    setJoined(true);
  };

  return (
    <div style={{ padding: 30 }}>

      <h2>👤 Patient Dashboard</h2>

      {/* BOOK OP */}
      <div>
        <input
          placeholder="Name"
          value={form.patientName}
          onChange={(e) =>
            setForm({ ...form, patientName: e.target.value })
          }
        />

        <input
          placeholder="Doctor"
          value={form.doctor}
          onChange={(e) =>
            setForm({ ...form, doctor: e.target.value })
          }
        />

        <input
          placeholder="Department"
          value={form.department}
          onChange={(e) =>
            setForm({ ...form, department: e.target.value })
          }
        />

        <input
          type="date"
          value={form.date}
          onChange={(e) =>
            setForm({ ...form, date: e.target.value })
          }
        />

        <button onClick={bookOP}>
          Book OP
        </button>
      </div>

      <hr />

      {/* ========================= */}
      {/* BEFORE JOIN → ONLY STATUS */}
      {/* ========================= */}
      {!joined ? (
        <div>
          <h3>📌 Your OP Status</h3>

          {queues.length === 0 ? (
            <p>No OP booked yet</p>
          ) : (
            queues.map((q) => (
              <div key={q._id}>
                <p>Token: {q.tokenNumber}</p>
                <p>Status: {q.status}</p>

                {q.status === "Confirmed" && (
                  <button onClick={() => joinQueue(q._id)}>
                    Join Queue
                  </button>
                )}
              </div>
            ))
          )}
        </div>

      ) : (

        /* ========================= */
        /* AFTER JOIN → FULL QUEUE   */
        /* ========================= */
        <div>
          <h3>🏥 Live OP Queue</h3>

          <p style={{ color: "green" }}>
            You are now in queue...
          </p>

          {queues.map((q) => (
            <div
              key={q._id}
              style={{
                border: "1px solid #ccc",
                margin: 10,
                padding: 10,
                borderRadius: 8
              }}
            >
              <p>Token: {q.tokenNumber}</p>
              <p>Status: {q.status}</p>

              {q.status === "InQueue" && (
                <b style={{ color: "green" }}>
                  🟢 Patient in OP
                </b>
              )}
            </div>
          ))}
        </div>
      )}

    </div>
  );
}

export default PatientDashboard;
